// Seleciona TODA conferencia com pagina de inscricao (registration_enabled), sem lista
// fixa de series ou nomes: webinar novo do marketing entra sozinho, recorrente OU avulso.
// - Ativas (agendadas/futuras): entram sempre.
// - Inativas (ja aconteceram): so as dos ultimos LOOKBACK_DIAS. Inscricao nao nasce depois
//   da sessao — o rescan curto cobre quem se inscreveu entre o ultimo run e o inicio da
//   sessao, e atualiza a presenca (Participou?). Historico antigo ja esta na planilha.
// - BLOQUEIO_RID: valvula de EXCLUSAO pontual (fail-open — na duvida a sala ENTRA;
//   linha indesejada na planilha e reversivel, lead perdido nao).
const LOOKBACK_DIAS = 36500;
const BLOQUEIO_RID = new Set(['17643']); // "teste1" (serie de teste conhecida)

function coletar(nomeNode) {
  const confs = [];
  let items = [];
  try { items = $(nomeNode).all(); } catch (e) { return confs; }
  for (const it of items) {
    const j = it.json;
    if (Array.isArray(j)) confs.push(...j);
    else if (j && Array.isArray(j.data)) confs.push(...j.data);
    else if (j && (j.id || j.recurring_config_id)) confs.push(j);
  }
  return confs;
}

const ativas = coletar('CM: conferências ativas');
const inativas = coletar('CM: conferências inativas');
const corte = Date.now() - LOOKBACK_DIAS * 24 * 60 * 60 * 1000;

const vistos = new Set();
const salas = [];
function considerar(c, origem) {
  if (!c || c.id == null) return;
  const idStr = String(c.id);
  if (vistos.has(idStr)) return;
  vistos.add(idStr);
  const temInscricao = c.registration_enabled === 1 || c.registration_enabled === true;
  if (!temInscricao) return;
  const rid = c.recurring_config_id == null ? '' : String(c.recurring_config_id);
  if (rid && BLOQUEIO_RID.has(rid)) return;
  if (origem === 'inativa') {
    const t = c.starts_at ? new Date(c.starts_at).getTime() : NaN;
    if (!Number.isFinite(t) || t < corte) return;
  }
  salas.push({ json: {
    salaId: c.id,
    salaNome: String(c.name || '').trim() || ('Sala ' + idStr),
    rid: rid,
    startsAt: c.starts_at || '',
    timezone: c.timezone || '',
  }});
}
for (const c of ativas) considerar(c, 'ativa');
for (const c of inativas) considerar(c, 'inativa');

salas.sort((a, b) => String(a.json.startsAt).localeCompare(String(b.json.startsAt)));
console.log('Salas a varrer: ' + salas.length + ' (de ' + (ativas.length + inativas.length) + ' conferencias vistas)');
return salas;

// O done do Loop A devolve os itens que voltaram do loop (inscritos), nao as salas.
// Recarrega a lista de salas do Selecionar para o Loop B varrer na MESMA ordem
// (a ordem identica e o que permite o join deterministico por iteracao no Montar linhas).
return $('Selecionar salas com inscrição').all().map((it) => ({ json: it.json }));

// Recebe a resposta de /sessions da sala atual do Loop B e emite 1 item por sessao
// realizada, carimbando o salaId (o payload de /sessions nao traz o id da sala).
// Sala futura ou sem sessao realizada -> retorna [] (o alwaysOutputData emite um item
// vazio, o GET de attendees da 404 e o Montar linhas trata como presenca indisponivel).
let sala = null;
try { const x = $('Loop B (presença por sala)').item; sala = x && x.json; } catch (e) {}
if (!sala || sala.salaId == null) {
  try { sala = $('Loop B (presença por sala)').all(1)[0].json; } catch (e) {}
}
if (!sala || sala.salaId == null) return [];

const out = [];
for (const it of $input.all()) {
  const j = it.json;
  if (!j || j.error) continue;
  const sess = Array.isArray(j) ? j : (Array.isArray(j.body) ? j.body : (j.id != null ? [j] : []));
  for (const s of sess) {
    if (s && s.id != null) out.push({ json: { salaId: sala.salaId, sessionId: s.id } });
  }
}
return out;

// Junta cada sala (ordem emitida pelo Selecionar) com os resultados das iteracoes dos
// dois loops. Join DETERMINISTICO por indice de execucao (runIndex): os loops processam
// 1 sala por vez, na MESMA ordem — a execucao i de cada no e exatamente a sala i.
// Nao depende de parsing de room_pin do link do inscrito.
const salas = $('Selecionar salas com inscrição').all().map((it) => it.json);
const linhas = [];
let httpErros = 0;

function flatten(items) {
  const regs = [];
  for (const it of items) {
    const j = it.json;
    if (!j) continue;
    if (j.error) { httpErros++; continue; }   // onError: continueRegularOutput
    if (Array.isArray(j)) regs.push(...j);
    else if (Array.isArray(j.body)) regs.push(...j.body);
    else if (j.email || j.visitor_nickname || j.id) regs.push(j);
    // item {} do alwaysOutputData (resposta vazia) nao entra em nenhum caso acima
  }
  return regs;
}

for (let i = 0; i < salas.length; i++) {
  const sala = salas[i];

  let regsItems = [];
  try { regsItems = $('CM: inscritos da sala').all(0, i); } catch (e) { regsItems = []; }
  const regs = flatten(regsItems);
  if (!regs.length) continue;

  // Presenca da iteracao i (Loop B varre as MESMAS salas na MESMA ordem do Loop A)
  let prepItems = [];
  try { prepItems = $('Preparar consulta de presença').all(0, i); } catch (e) { prepItems = []; }
  const houveSessao = prepItems.some((it) => it.json && it.json.sessionId != null);

  let attItems = [];
  try { attItems = $('CM: presentes da sessão').all(0, i); } catch (e) { attItems = []; }
  const attErro = attItems.some((it) => it.json && it.json.error);
  const presentes = new Set();
  for (const a of flatten(attItems)) {
    const em = (a.email || '').toString().toLowerCase().trim();
    if (em) presentes.add(em);
  }

  for (const r of regs) {
    const f = (r && r.fields) || {};
    const geo = (r && r.geo) || {};
    const email = (r.email || f['Email Address'] || '').toString().toLowerCase().trim();
    if (!email) continue;

    // Sim = email esta nos attendees da sessao realizada.
    // Nao = sessao realizada, consulta de presenca OK e email fora da lista.
    // ''  = sessao ainda nao aconteceu, ou presenca indisponivel (erro de consulta).
    let participou = '';
    if (houveSessao) {
      if (presentes.has(email)) participou = 'Sim';
      else if (!attErro) participou = 'Não';
    }

    linhas.push({ json: {
      'Data inscrição': r.registration_date || r.registration_confirmed || '',
      'Nome': r.visitor_nickname || f['Name'] || '',
      'Email': email,
      'Empresa': f['Company'] || '',
      'País': geo.country || '',
      'Cidade': geo.city || '',
      'Marca/Sala': sala.salaNome,
      'Série': sala.rid,
      'Sessão': sala.startsAt,
      'Origem': r.http_referer || '',
      'Link de acesso': r.url || '',
      'Participou?': participou,
      'Chave': email + '|' + sala.salaId,
    }});
  }
}
if (httpErros) console.log('Respostas HTTP com erro (puladas/presenca indisponivel): ' + httpErros);
console.log('Linhas montadas: ' + linhas.length);
return linhas;
